 view.onchange=()=>{selected=null;fitWidth=null;zoom=1;render();};query.oninput=()=>{fitWidth=null;render();};zoomInput.oninput=()=>{zoom=Number(zoomInput.value)/100;applyZoom();};root.querySelector('.map-fit').onclick=()=>{if(!layout)return;if(view.value==='mesh'){const projects=sequenceMesh(getSequences()).nodes,filtered=projects.filter(p=>(p.name+' '+p.projectId).toLowerCase().includes(query.value.toLowerCase()));for(let percent=100;percent>=40;percent-=5){const scale=percent/100,width=(scroll.clientWidth-20)/scale,trial=categoryMapLayout(filtered,width,projects);if(trial.height*scale<=scroll.clientHeight-20||percent===40){zoom=scale;fitWidth=width;render();break;}}}else{zoom=Math.max(.4,Math.min(1,(scroll.clientWidth-18)/layout.width,(scroll.clientHeight-18)/layout.height));applyZoom();}scroll.scrollTop=0;scroll.scrollLeft=0;};
 function clearSelection(){if(selected!==null&&selected!==undefined){selected=null;render();}}
 scroll.onclick=event=>{if(!event.target.closest('.map-node'))clearSelection();};root.addEventListener('keydown',event=>{if(event.key==='Escape')clearSelection();});
 for(const selector of ['.map-runtime','.map-preferences'])root.querySelector(selector).onchange=render;
